$string['helpcard01'] = 'Este é o cartão de um leitor, tal como ele o vê: no telemóvel, na sala de aula ou no computador da biblioteca.';
$string['helpcard02'] = 'A sua flor cresce com o que acontece no balcão: voltar, explorar novos cantinhos, partilhar o que achou de um livro e terminar o que começa. Nunca murcha.';
